def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    opp_def = 0
    for m, o in history:
        if o == 'D':
            opp_def += 1
    if opp_def == 0:
        return 'D'
    if n >= 10 and opp_def > n * 0.8:
        return 'D'
    if n == 99:
        return 'D'
    my_last, opp_last = history[-1]
    if opp_last == 'C':
        return 'C'
    else:
        if my_last == 'D' and n >= 2:
            _, opp_prev = history[-2]
            if opp_prev == 'D':
                if n >= 3:
                    _, opp_prev2 = history[-3]
                    if opp_prev2 == 'D':
                        return 'D'
                return 'C'
        return 'D'
